INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch09$PT159-S1-Q14$batch09$, 159, 1, 14, $batch09$Principle-Strengthen$batch09$, $batch09$Environmentalist: The adoption of genetically engineered crops in agriculture is moving so rapidly and is monitored so loosely that it poses a significant risk of damaging sensitive ecosystems. One such crop had already been widely planted when a study found that it could threaten monarch butterflies. Therefore, before any new genetically engineered crop is put into agricultural production, rigorous testing of its safety should be required.$batch09$, $batch09$Which one of the following principles, if valid, most helps to justify the environmentalist’s reasoning?$batch09$, $batch09$C$batch09$, true, $batch09$Batch 09; question text from local bank.$batch09$ FROM lr_sections s WHERE s.preptest=159 AND s.section=1 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch09$PT159-S1-Q14$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$A$batch09$, $batch09$A genetically engineered crop should not be put into agricultural production if rigorous testing has shown it to be risky.$batch09$, $batch09$Wrong Order$batch09$, false FROM lr_questions q WHERE q.qid=$batch09$PT159-S1-Q14$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$A$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$B$batch09$, $batch09$If a crop has no potential for posing environmental risks, it may be put into agricultural production without testing of its safety.$batch09$, $batch09$Wrong Trigger$batch09$, false FROM lr_questions q WHERE q.qid=$batch09$PT159-S1-Q14$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$B$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$C$batch09$, $batch09$No crop that might present risks to the environment should be allowed into agricultural production unless its safety has been thoroughly tested.$batch09$, $batch09$Correct$batch09$, true FROM lr_questions q WHERE q.qid=$batch09$PT159-S1-Q14$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$C$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$D$batch09$, $batch09$If rigorous testing of any genetically engineered crop that is in agricultural production shows that that crop poses environmental risks, production of that crop should be discontinued.$batch09$, $batch09$Wrong Timing$batch09$, false FROM lr_questions q WHERE q.qid=$batch09$PT159-S1-Q14$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$D$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$E$batch09$, $batch09$If rigorous studies do not find evidence that a crop would present risks if it is brought into agricultural production, no further testing of that crop’s safety is required.$batch09$, $batch09$Wrong Trigger$batch09$, false FROM lr_questions q WHERE q.qid=$batch09$PT159-S1-Q14$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$E$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch09$PT159-S1-Q14$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch09$Conclusion$batch09$, $batch09$Before any new genetically engineered crop goes into agricultural production, rigorous safety testing should be required.$batch09$), (1, $batch09$Evidence$batch09$, $batch09$These crops are being adopted fast and monitored loosely, which poses a significant risk to ecosystems. One crop was already widely planted before a study found it could threaten monarch butterflies.$batch09$), (2, $batch09$Evaluate$batch09$, $batch09$The evidence says these crops might be risky. The conclusion requires testing before production. So the principle has to say that a crop that might be risky can't go into production until it's tested.$batch09$), (3, $batch09$Goal$batch09$, $batch09$A crop that might pose environmental risks must be tested before it is put into production.$batch09$)) v(position,label,body) WHERE q.qid=$batch09$PT159-S1-Q14$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch09$A$batch09$, $batch09$This says what to do after testing finds a risk. It assumes the testing already happened. The conclusion is about requiring the testing in the first place.$batch09$), ($batch09$B$batch09$, $batch09$This applies to crops with no potential risk. The environmentalist says these crops are risky, so B doesn't apply.$batch09$), ($batch09$C$batch09$, $batch09$"Unless" means "if not": if a crop might pose risks and hasn't been thoroughly tested, it can't go into production. GE crops might pose risks, so they need testing before production. That's the conclusion.$batch09$), ($batch09$D$batch09$, $batch09$This covers crops already in production. The conclusion is about testing before production begins.$batch09$), ($batch09$E$batch09$, $batch09$This tells us when testing can stop. It never requires testing before production.$batch09$)) v(letter,body) WHERE q.qid=$batch09$PT159-S1-Q14$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
